#!/usr/bin/env python3
"""Embed the unmodified UCUM XML as a string; no table entries are rewritten."""
import hashlib
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
source = ROOT / "standards/ucum-essence.xml"
manifest = json.loads((ROOT / "standards/sources.json").read_text(encoding="utf-8"))
entry = next(item for item in manifest if item["file"] == source.name)
assert hashlib.sha256(source.read_bytes()).hexdigest() == entry["sha256"]
text = source.read_bytes().decode("utf-8")
content = (
    "// Generated by scripts/embed_catalog.py. The string preserves the upstream XML.\n"
    "// UCUM copyright and license: standards/UCUM-LICENSE.md.\n"
    "///|\n"
    "const Essence : String =\n" + "\n".join("  #|" + line for line in text.split("\n")) + "\n"
)
destination = ROOT / "catalog_data.mbt"
if "--check" in sys.argv:
    assert destination.read_text(encoding="utf-8") == content, "catalog embedding is stale"
else:
    destination.write_bytes(content.encode("utf-8"))
